/* ---------- chemins de terre : se créent entre les bâtiments ----------
   Procédural (sable tassé assombri, tracé stable par graine) — remplaçable
   plus tard par un decal du propriétaire. Chaque bâtiment se relie au
   voisin (ou à la balise) le plus proche déjà en place. */
let pathCache = { key: "", segs: [] };
function pathSegs() {
  const key = S.buildings.map((b) => b.x + "," + b.y).join(";");
  if (pathCache.key === key) return pathCache.segs;
  const segs = [];
  const nodes = [{ x: SRC.x, y: SRC.y }];
  for (const b of S.buildings) {
    let best = null, bd = 1e9;
    for (const n of nodes) {
      const d = Math.hypot(b.x - n.x, b.y - n.y);
      if (d < bd) { bd = d; best = n; }
    }
    if (best && bd <= 6) segs.push({ ax: b.x, ay: b.y, bx: best.x, by: best.y });
    nodes.push({ x: b.x, y: b.y });
  }
  pathCache = { key, segs };
  return segs;
}
function drawPaths() {
  const segs = pathSegs();
  if (!segs.length) return;
  const z = cam.z;
  ctx.save();
  plateauClipPath(); ctx.clip();
  ctx.globalCompositeOperation = "multiply";
  for (const s of segs) {
    const A = w2s(s.ax, s.ay), B = w2s(s.bx, s.by);
    const r = mulberry32(hash2(s.ax * 7 + s.bx, s.ay * 13 + s.by));
    const n = Math.max(6, Math.round(Math.hypot(B.x - A.x, B.y - A.y) / (9 * z)));
    for (let i = 0; i <= n; i++) {
      const k = 0.16 + (i / n) * 0.68; // on s'arrête avant les socles
      const px2 = A.x + (B.x - A.x) * k + (r() - 0.5) * 7 * z;
      const py2 = A.y + (B.y - A.y) * k + (r() - 0.5) * 4 * z;
      ctx.beginPath();
      ctx.ellipse(px2, py2, (6 + r() * 3) * z, (3 + r() * 1.4) * z, 0, 0, Math.PI * 2);
      ctx.fillStyle = "rgba(206, 178, 148, 0.5)"; // multiply : sable tassé
      ctx.fill();
    }
  }
  ctx.globalCompositeOperation = "source-over";
  ctx.restore();
}
function drawRockSprite(x, y) {
  if (!ROCK.ok) return;
  const info = tileAt(x, y), p = w2s(x, y), z = cam.z;
  const s0 = (0.5 + 0.28 * ((info.j * 11) % 1)) * TW * 0.9 * z;
  const h0 = s0 * ROCK.ih / ROCK.iw;
  ctx.drawImage(ROCK.img, p.x - s0 / 2, p.y + TH * 0.34 * z - h0 * ROCK.groundY, s0, h0);
}
function plateauClipPath() { // pentagone : bords-falaises exacts, ouvert vers le haut
  const z = cam.z;
  const pw = w2s(bmin(), bmax()), pe = w2s(bmax(), bmin()), ps = w2s(bmax(), bmax());
  const wx = pw.x - TW / 2 * z, ex = pe.x + TW / 2 * z;
  ctx.beginPath();
  ctx.moveTo(wx, pw.y);
  ctx.lineTo(wx, -1e6);
  ctx.lineTo(ex, -1e6);
  ctx.lineTo(ex, pe.y);
  ctx.lineTo(ps.x, ps.y + TH / 2 * z);
  ctx.closePath();
}
function drawCrystalSprite(x, y) {
  if (!CRX.ok) return;
  const info = tileAt(x, y), z = cam.z, p = w2s(x, y);
  const sz = crysSize(x, y), m = CRX.m[sz];
  const sw = CRX.w[sz] * (0.94 + 0.12 * ((info.j * 7) % 1)) * TW * z, sh = sw * m.hw;
  ctx.save();
  plateauClipPath(); ctx.clip();
  // l'ancre est le centre du disque de sol fissuré : il épouse la case
  ctx.drawImage(crxImg(sz), p.x - m.gax * sw, p.y - m.gay * sh, sw, sh);
  ctx.restore();
  // compteur de gisement : dès qu'un drone extrait, ou que le stock est entamé
  const max = crysMax(x, y), st = crysStock(x, y);
  const mining = S.units.some((u) => u.t === "recolteur" && u.x === x && u.y === y);
  if (!mining && st >= max) return;
  const fs = Math.max(9, 8.8 * z);
  ctx.font = "700 " + fs + "px system-ui, sans-serif";
  const txt = "💎 " + Math.max(0, Math.ceil(st));   // ce qu'un gisement contient, c'est du cristal
  const tw2 = ctx.measureText(txt).width, pw = tw2 + 11 * z, ph = fs + 8;
  const bx = p.x - pw / 2;
  // jamais sous le HUD ni hors écran (fort zoom) : on borne dans la vue
  const by = Math.min(H - ph - 8, Math.max(52 * DPR, p.y - m.gay * sh - ph - 4 * z));
  const arrondi = (x2, y2, w2, h2, r2) => {
    ctx.beginPath();
    if (ctx.roundRect) ctx.roundRect(x2, y2, w2, h2, r2);
    else ctx.rect(x2, y2, w2, h2); // vieux WebKit : rectangle simple
  };
  arrondi(bx, by, pw, ph, ph / 2);
  ctx.fillStyle = "rgba(6,10,20,.74)"; ctx.fill();
  ctx.strokeStyle = mining ? "rgba(78,242,224,.75)" : "rgba(78,242,224,.32)";
  ctx.lineWidth = 1; ctx.stroke();
  ctx.fillStyle = mining ? "#bdfcf4" : "#7fa9b9";
  ctx.textAlign = "center"; ctx.textBaseline = "middle";
  ctx.fillText(txt, p.x, by + ph / 2);
  arrondi(bx + 3, by + ph - 2.5, Math.max(2, (pw - 6) * Math.min(1, st / max)), 2, 1);
  ctx.fillStyle = "#4ef2e0"; ctx.fill();
  ctx.textAlign = "left"; ctx.textBaseline = "alphabetic";
}

function drawBuilding(b, t) {
  const p = w2s(b.x, b.y), z = cam.z;
  const def = BT[b.t];
  const tk = tsprKey(b.t, b.l);
  const ts = TSPR[tk];
  if (ts && ts.ok) { // tuile-bâtiment : halo centré sur la case, contenu dans la case
    const img = tsprImg(tk);
    const sw = ts.w * TW * z, sh = sw * ts.hw;
    ctx.save();
    plateauClipPath(); ctx.clip();
    ctx.drawImage(img, p.x - ts.ax * sw, p.y + TH * ts.oy * z - ts.ay * sh, sw, sh);
    ctx.restore();
    return;
  }
  const hgt = (16 + Math.min(b.l, 10) * 5) * z;
  const w = TW * 0.62 * z, h = TH * 0.62 * z;
  // socle
  diamond(ctx, p.x, p.y, TW * 0.8 * z, TH * 0.8 * z);
  ctx.fillStyle = "#22262e"; ctx.fill();
  const spr = SPRITE_IMG[b.t];
  if (spr && spr.meta) {
    const k = TW * z / (spr.meta.rightX - spr.meta.leftX);
    const sw = spr.w * k, sh = spr.h * k;
    const sx0 = p.x - (TW / 2) * z - spr.meta.leftX * k;
    const sy0 = p.y - spr.meta.sideY * k;
    ctx.drawImage(spr.img, sx0, sy0, sw, sh);
    // fumée des cheminées
    for (const ch of spr.smoke) {
      for (let i = 0; i < 3; i++) {
        const ph2 = ((t / 2600) + i / 3 + ch.fx) % 1;
        const sy2 = sy0 + ch.fy * sh - ph2 * 26 * z;
        ctx.globalAlpha = 0.34 * (1 - ph2);
        ctx.beginPath();
        ctx.arc(sx0 + ch.fx * sw + Math.sin((t / 900) + i * 2.1) * 3 * z, sy2, (3 + ph2 * 6) * z, 0, Math.PI * 2);
        ctx.fillStyle = "#c9ced8"; ctx.fill();
      }
    }
    ctx.globalAlpha = 1;
    return;
  }
  isoBox(p.x, p.y, w, h, hgt, def.col);
  // antenne niv 3+
  if (b.l >= 3) {
    ctx.strokeStyle = "#d7dade"; ctx.lineWidth = 1.5 * z;
    ctx.beginPath();
    ctx.moveTo(p.x, p.y - hgt - h / 2);
    ctx.lineTo(p.x, p.y - hgt - h / 2 - 12 * z);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(p.x, p.y - hgt - h / 2 - 13 * z, 2.5 * z, 0, Math.PI * 2);
    ctx.fillStyle = def.col;
    ctx.shadowColor = def.col; ctx.shadowBlur = 8;
    ctx.fill(); ctx.shadowBlur = 0;
  }
}
// La balise centrale : asset définitif de la Source (bake : structure +
// anneau de débris + faisceau en matte de différence, sol aligné plateau)
const SRCB = { ok: false, mips: {}, ax: 0.499, ay: 0.769, hw: 1.071, w: 0.72, oy: 0 };
(function () {
  const img = new Image();
  img.onload = () => { SRCB.img = img; SRCB.ok = true; };
  img.src = "data:image/webp;base64,";
})();
function srcbImg() {
  const px2 = SRCB.w * TILE.world * cam.z * DPR;
  const w = [160, 320, SRCB.img.width].find((v) => v >= px2) || SRCB.img.width;
  let c = SRCB.mips[w];
  if (!c) {
    c = SRCB.mips[w] = document.createElement("canvas");
    c.width = w; c.height = Math.round(w * SRCB.img.height / SRCB.img.width);
    c.getContext("2d").drawImage(SRCB.img, 0, 0, c.width, c.height);
  }
  return c;
}
function drawSource(t) {
  const p = w2s(SRC.x, SRC.y), z = cam.z;
  if (SRCB.ok) {
    const sw = SRCB.w * TW * z, sh = sw * SRCB.hw;
    ctx.drawImage(srcbImg(), p.x - SRCB.ax * sw, p.y + TH * SRCB.oy * z - SRCB.ay * sh, sw, sh);
    // halo léger animé le long du faisceau (toute la hauteur du faisceau de l'asset)
    const topY = p.y - SRCB.ay * sh + sh * 0.02;
    const baseY = p.y - 4 * z;
    const bw2 = (6.5 + 1.6 * Math.sin(t / 300)) * z;
    const g2 = ctx.createLinearGradient(p.x, topY, p.x, baseY);
    g2.addColorStop(0, "rgba(111,216,242,0)");
    g2.addColorStop(0.5, "rgba(56,169,255,.26)");
    g2.addColorStop(1, "rgba(190,240,255,.42)");
    ctx.fillStyle = g2;
    ctx.fillRect(p.x - bw2 / 2, topY, bw2, baseY - topY);
    if (soutePrete()) {
      const bob = Math.sin(t / 500) * 4 * z;
      ctx.font = Math.round(15 * z) + "px " + UI_FONT;
      ctx.textAlign = "center";
      ctx.globalAlpha = 0.7 + 0.3 * Math.sin(t / 600);
      ctx.shadowColor = "#a06bff"; ctx.shadowBlur = 10;
      ctx.fillText("📼", p.x + TW * 0.34 * z, p.y - 46 * z + bob);
      ctx.shadowBlur = 0; ctx.globalAlpha = 1;
    }
    return;
  }
  // plateforme circulaire (contenue dans la cellule)
  ctx.beginPath();
  ctx.ellipse(p.x, p.y, TW * 0.28 * z, TH * 0.28 * z, 0, 0, Math.PI * 2);
  ctx.fillStyle = "#2a2d33"; ctx.fill();
  ctx.strokeStyle = "#4a5058"; ctx.lineWidth = 1.6 * z; ctx.stroke();
  ctx.beginPath();
  ctx.ellipse(p.x, p.y, TW * 0.19 * z, TH * 0.19 * z, 0, 0, Math.PI * 2);
  ctx.strokeStyle = "#38a9ff"; ctx.globalAlpha = 0.5 + 0.3 * Math.sin(t / 400);
  ctx.stroke(); ctx.globalAlpha = 1;
  // faisceau
  const bh = 95 * z, bw = 6.5 * z * (1 + 0.12 * Math.sin(t / 300));
  const g = ctx.createLinearGradient(p.x, p.y - bh, p.x, p.y);
  g.addColorStop(0, "rgba(111,216,242,0)");
  g.addColorStop(0.6, "rgba(56,169,255,.5)");
  g.addColorStop(1, "rgba(190,240,255,.95)");
  ctx.fillStyle = g;
  ctx.fillRect(p.x - bw / 2, p.y - bh, bw, bh);
  // cœur (l'Étincelle)
  ctx.beginPath();
  ctx.arc(p.x, p.y - 5 * z, (3.8 + 1.2 * Math.sin(t / 200)) * z, 0, Math.PI * 2);
  ctx.fillStyle = "#eaffff";
  ctx.shadowColor = "#6fd8f2"; ctx.shadowBlur = 18;
  ctx.fill(); ctx.shadowBlur = 0;
  // compartiment scellé : main tendue discrète (quête annexe)
  if (soutePrete()) {
    const bob = Math.sin(t / 500) * 4 * z;
    ctx.font = Math.round(15 * z) + "px " + UI_FONT;
    ctx.textAlign = "center";
    ctx.globalAlpha = 0.7 + 0.3 * Math.sin(t / 600);
    ctx.shadowColor = "#a06bff"; ctx.shadowBlur = 10;
    ctx.fillText("📼", p.x + TW * 0.28 * z, p.y - 40 * z + bob);
    ctx.shadowBlur = 0; ctx.globalAlpha = 1;
  }
}
function drawLink(b, t) {
  const a = w2s(b.x, b.y), c = w2s(SRC.x, SRC.y);
  ctx.strokeStyle = BT[b.t].col;
  ctx.globalAlpha = 0.32;
  ctx.lineWidth = 1.6 * cam.z;
  ctx.setLineDash([6 * cam.z, 8 * cam.z]);
  ctx.lineDashOffset = -t / 40;
  ctx.beginPath();
  ctx.moveTo(a.x, a.y);
  ctx.quadraticCurveTo((a.x + c.x) / 2, (a.y + c.y) / 2 - 14 * cam.z, c.x, c.y);
  ctx.stroke();
  ctx.setLineDash([]); ctx.globalAlpha = 1;
}
function drawCable(l, t) {
  const na = nodeAt(l.a), nb = nodeAt(l.b);
  if (!na || !nb) return;
  const a = w2s(na.x, na.y), b = w2s(nb.x, nb.y), z = cam.z;
  const my = (a.y + b.y) / 2 + 10 * z;
  ctx.strokeStyle = "#e8a24d";
  ctx.globalAlpha = 0.8;
  ctx.lineWidth = 1.8 * z;
  ctx.beginPath();
  ctx.moveTo(a.x, a.y + 6 * z);
  ctx.quadraticCurveTo((a.x + b.x) / 2, my, b.x, b.y + 6 * z);
  ctx.stroke();
  ctx.globalAlpha = 1;
  if (netConnected(l.a) && netConnected(l.b)) {
    const ph = ((t / 2600) + (na.x * 3 + nb.y * 7) * 0.137) % 1;   // glissement paisible (0,9 s -> 2,6 s le parcours)
    const inv = 1 - ph;
    const qx = inv * inv * a.x + 2 * inv * ph * ((a.x + b.x) / 2) + ph * ph * b.x;
    const qy = inv * inv * (a.y + 6 * z) + 2 * inv * ph * my + ph * ph * (b.y + 6 * z);
    ctx.beginPath();
    ctx.arc(qx, qy, 2.4 * z, 0, Math.PI * 2);
    ctx.fillStyle = "#ffe9b0";
    ctx.shadowColor = "#ffd27a"; ctx.shadowBlur = 6;
    ctx.fill(); ctx.shadowBlur = 0;
  }
}
const ORBIMG = { ok: false };
(function () {
  const img = new Image();
  img.onload = () => { ORBIMG.img = img; ORBIMG.ok = true; };
  img.src = "data:image/webp;base64,";
})();
function drawOrb(o, t) {
  const p = w2s(o.x, o.y), z = cam.z;
  const oy = p.y - 34 * z - Math.sin((t + o.born) / 350) * 5 * z;
  o.sx = p.x; o.sy = oy;
  if (ORBIMG.ok) {
    const dw = 19.5 * z;   // éclat réduit d'un quart (26 -> 19,5) — retour user 15/08
    ctx.shadowColor = "rgba(78, 242, 224, .85)";
    ctx.shadowBlur = 12 * z;
    ctx.drawImage(ORBIMG.img, p.x - dw / 2, oy - dw / 2, dw, dw);
    ctx.shadowBlur = 0;
    return;
  }
  ctx.beginPath();
  ctx.arc(p.x, oy, 6 * z, 0, Math.PI * 2);   // repli sans asset : même réduction d'un quart
  const g = ctx.createRadialGradient(p.x, oy, 1, p.x, oy, 6.75 * z);
  g.addColorStop(0, "#eaffff"); g.addColorStop(0.5, "#4ef2e0"); g.addColorStop(1, "rgba(78,242,224,0)");
  ctx.fillStyle = g;
  ctx.shadowColor = "#4ef2e0"; ctx.shadowBlur = 12;
  ctx.fill(); ctx.shadowBlur = 0;
}

function drawMob(m, t) {
  let px, py;
  if (m.atk) {
    // le chasseur approche : le parasite tremble
    const p = w2s(m.x, m.y);
    px = p.x + Math.sin(t / 40) * 2; py = p.y;
  } else {
    const p = w2s(m.x, m.y);
    px = p.x; py = p.y + Math.sin((t + m.born) / 300) * 2;
  }
  m.sx = px; m.sy = py;
  const z = cam.z;
  ctx.strokeStyle = "#7a1f3d"; ctx.lineWidth = 1.5 * z;
  for (let i = 0; i < 6; i++) {
    const a = (i / 6) * Math.PI * 2 + Math.sin(t / 200) * 0.2;
    ctx.beginPath();
    ctx.moveTo(px, py);
    ctx.lineTo(px + Math.cos(a) * 13 * z, py + Math.sin(a) * 8 * z + 3 * z);
    ctx.stroke();
  }
  ctx.beginPath();
  ctx.ellipse(px, py - 2 * z, 8 * z, 6 * z, 0, 0, Math.PI * 2);
  ctx.fillStyle = "#3d0f22";
  ctx.shadowColor = "#ff4d8a"; ctx.shadowBlur = 10 + 4 * Math.sin(t / 250);
  ctx.fill(); ctx.shadowBlur = 0;
  ctx.beginPath();
  ctx.arc(px - 2.5 * z, py - 3 * z, 1.6 * z, 0, Math.PI * 2);
  ctx.arc(px + 2.5 * z, py - 3 * z, 1.6 * z, 0, Math.PI * 2);
  ctx.fillStyle = "#ff4d8a"; ctx.fill();
}
// Drone ouvrier : asset définitif (fond transparent), vibration légère
const DRN = { ok: false, mips: {}, hw: 0.857 };
// Largeur du drone ouvrier, en fraction de case — réduite d'un quart le 15/08
// (0,33 -> 0,2475) à la demande du propriétaire. Une seule constante : le drone
// posé et son aperçu de pose ne peuvent pas diverger.
const DRONE_W = 0.2475;
(function () {
  const img = new Image();
  img.onload = () => { DRN.img = img; DRN.ok = true; };
  img.src = "data:image/webp;base64,";
})();
function drnImg() {
  const px2 = 0.4 * TILE.world * cam.z * DPR;
  const w = [96, 192, DRN.img.width].find((v) => v >= px2) || DRN.img.width;
  let c = DRN.mips[w];
  if (!c) {
    c = DRN.mips[w] = document.createElement("canvas");
    c.width = w; c.height = Math.round(w * DRN.img.height / DRN.img.width);
    c.getContext("2d").drawImage(DRN.img, 0, 0, c.width, c.height);
  }
  return c;
}
function drawUnit(u, t) {
  const z = cam.z;
  let px, py;
  if (u.t === "chasseur" && u.anim) {
    px = u.anim.x; py = u.anim.y;
  } else {
    const p = w2s(u.x, u.y);
    px = p.x + (u.t === "chasseur" ? 18 * z : 0);
    py = p.y - (u.t === "recolteur" ? 26 : 22) * z -
      (u.t === "recolteur" ? 0 : Math.sin((t + (u.x + u.y) * 500) / 400) * 4 * z);
  }
  if (u.fly) { // vol de déploiement depuis la Source
    const k = (t - u.fly.t0) / u.fly.dur;
    if (k >= 1 || k < 0) delete u.fly;
    else {
      const p0 = w2s(u.fly.x0, u.fly.y0), e = 1 - Math.pow(1 - k, 3);
      px = p0.x + (px - p0.x) * e;
      py = (p0.y - 46 * z) + (py - (p0.y - 46 * z)) * e;
    }
  }
  if (u.t === "recolteur") {
    // vibration très légère (pas de ballant haut-bas)
    const vx = px + Math.sin(t / 23 + u.x * 5) * 0.14 * z;
    const vy = py + Math.cos(t / 29 + u.y * 7) * 0.14 * z;
    if (DRN.ok) {
      const vw = DRONE_W * TW * z, vh = vw * DRN.hw;
      // rayon de récolte vers les cristaux
      ctx.strokeStyle = "rgba(78,242,224,.4)"; ctx.lineWidth = 1.5 * z;
      ctx.beginPath(); ctx.moveTo(vx, vy + vh * 0.28); ctx.lineTo(vx, vy + 26 * z); ctx.stroke();
      ctx.drawImage(drnImg(), vx - vw / 2, vy - vh / 2, vw, vh);
    } else {
      ctx.beginPath();
      ctx.ellipse(vx, vy, 9 * z, 5 * z, 0, 0, Math.PI * 2);
      ctx.fillStyle = "#e8e6e0"; ctx.fill();
      ctx.strokeStyle = "#82878f"; ctx.lineWidth = 1; ctx.stroke();
      ctx.strokeStyle = "rgba(78,242,224,.4)"; ctx.lineWidth = 1.5 * z;
      ctx.beginPath(); ctx.moveTo(vx, vy + 4 * z); ctx.lineTo(vx, vy + 22 * z); ctx.stroke();
    }
  } else {
    ctx.beginPath();
    ctx.moveTo(px, py - 7 * z);
    ctx.lineTo(px + 6 * z, py + 5 * z);
    ctx.lineTo(px - 6 * z, py + 5 * z);
    ctx.closePath();
    ctx.fillStyle = "#e8e6e0"; ctx.fill();
    ctx.strokeStyle = "#82878f"; ctx.lineWidth = 1; ctx.stroke();
    ctx.beginPath();
    ctx.arc(px, py + 6.5 * z, 2 * z, 0, Math.PI * 2);
    ctx.fillStyle = "#38a9ff";
    ctx.shadowColor = "#38a9ff"; ctx.shadowBlur = 8;
    ctx.fill(); ctx.shadowBlur = 0;
  }
}

